/**
 * VEML HTML authoring dialect (conformance G.1–G.6).
 *
 * A second INPUT syntax over the SAME internal document model.
 * `.veml` XML stays the canonical interchange format; the `veml-*` HTML dialect
 * is the authoring-first syntax for humans and LLMs. Both front-ends produce an
 * identical `VemlDocument` and share the entire pipeline from there.
 *
 * Why `veml-` PREFIXED elements: the dialect is parsed with a
 * REAL HTML parser (`DOMParser`, `text/html`), and bare VEML names collide with
 * HTML's per-element content models — `input` is void, `image` is rewritten to
 * `img`, nested `button` auto-closes, `script` is raw-text. Hyphenated
 * `veml-*` names are generic "unknown elements" with the generic content model:
 * children nest exactly as written. They are ALSO valid custom-element names —
 * which we NEVER register (`customElements.define` is never called).
 *
 * THE HARD CONSTRAINT: the document is INERT text we
 * parse ONCE. No custom elements, no DOM-mirrored scene graph, no A-Frame-style
 * two-tree sync. The parsed `HTMLDocument` is read into `VemlDocument` and
 * DISCARDED — a one-way parse, exactly like the XML path.
 *
 * Driftlessness: the per-subtype payload REUSES the XML parser's
 * `SUBTYPE_FIELDS` catalog — the dialect reads each `wire` name as an ATTRIBUTE
 * rather than a child element, but the [key, wire, kind, dflt] table is
 * single-source in parser.ts. XSD defaults come from the SAME documentModel.ts
 * constants. Zero Babylon imports (main-bundle core; the src/veml zero-Babylon
 * guard covers this file).
 *
 * Ergonomics folds (the FROZEN vocabulary): two authoring conveniences, each
 * keeping this file's discipline (SAME `VemlDocument`, own-property-guarded
 * dispatch, inert one-way parse, ZERO new report kind, ZERO Babylon, an
 * XML-equivalence deep-equal twin):
 *   (1) FRIENDLY ELEMENT ALIASES (`veml-cube`→`cubemesh`, …) — a small alias
 *       table resolving a friendly localName to its canonical `xsi:type` BEFORE
 *       dispatch (own-property-guarded — a `veml-constructor` never resolves).
 *   (2) `<veml-sky>` — a lite-procedural-sky background element reusing the XML
 *       parser's exported `SKY_ATTRS` catalog (single-source; the visual sky
 *       is not rendered here — a `veml-sky` world loads with the neutral-IBL
 *       fallback). Conformance G.10/G.11; the set is FROZEN (conformance
 *       G.12).
 *
 * Copyright 2019-2026.
 */

import type {
  VemlBackground,
  VemlControlFlags,
  VemlDocument,
  VemlEntity,
  VemlEntityBase,
  VemlEnvironment,
  VemlLink,
  VemlLiteProceduralSky,
  VemlInputEvent,
  VemlMetadata,
  VemlQuaternion,
  VemlScriptRef,
  VemlSynchronizationService,
  VemlResourceRef,
  VemlTransform,
  VemlVec2,
  VemlVec3,
} from './documentModel';
import {
  DEFAULT_POSITION,
  DEFAULT_POSITION_PERCENT,
  DEFAULT_ROTATION,
  DEFAULT_SCALE,
  DEFAULT_SIZE,
  DEFAULT_SIZE_PERCENT,
} from './documentModel';
import {
  CONTROL_FLAG_FIELDS,
  LEGACY_METADATA_CHILDREN,
  SKY_ATTRS,
  SUBTYPE_FIELDS,
  type FieldSpec,
  type LegacyMetadataChild,
  type VemlParseReport,
  type VemlParseResult,
  type VemlParseWarning,
} from './parser';
import { followableWorldUri, resolveWorldUri } from './uriResolve';
import { parseWorld40Xml } from './parse40';
import { containsVemlElement, isHtmlWorldUrl, mimeIsHtml } from './htmlRouting';

const VEML_PREFIX = 'veml-';
/** Structure elements (root-only) — NOT entity types. */
const STRUCTURE_LOCALS = new Set(['veml-world', 'veml-metadata', 'veml-background', 'veml-spawn', 'veml-sky']);

/**
 * Friendly element aliases (ergonomics fold 1) — a friendly localName
 * suffix → its canonical `xsi:type`. Authoring `veml-cube` is the ergonomic win
 * over `veml-cubemesh`; both remain valid (aliases are additive). Resolved
 * OWN-PROPERTY-GUARDED (a wire `veml-constructor`/`veml-__proto__` must NOT
 * resolve through this table to a prototype member — the prototype-pollution
 * guard, the same rule as SUBTYPE_FIELDS dispatch). The
 * canonical type is what lands in `base.type`, so `veml-cube` deep-equals
 * `veml-cubemesh` deep-equals XML `xsi:type="cubemesh"` (conformance G.10).
 */
const ELEMENT_ALIASES: Record<string, string> = {
  cube: 'cubemesh',
  sphere: 'spheremesh',
  cylinder: 'cylindermesh',
  capsule: 'capsulemesh',
  plane: 'planemesh',
  cone: 'conemesh',
  torus: 'torusmesh',
  pyramid: 'rectangularpyramidmesh',
  prism: 'prismmesh',
  tetrahedron: 'tetrahedronmesh',
  arch: 'archmesh',
  model: 'mesh',
};

/** Resolve a friendly alias to its canonical `xsi:type` (own-property-guarded). */
function resolveAlias(raw: string): string {
  return Object.prototype.hasOwnProperty.call(ELEMENT_ALIASES, raw)
    ? ELEMENT_ALIASES[raw]!
    : raw;
}

// ---------------------------------------------------------------------------
// Detection helpers (G.1), which live in the always-loaded htmlRouting.ts.
// ---------------------------------------------------------------------------

export { containsVemlElement, isHtmlWorldUrl, mimeIsHtml };

// ---------------------------------------------------------------------------
// Value readers — the dialect reads ATTRIBUTES where the XML parser reads child
// elements/text. Parse + default semantics MIRROR parser.ts exactly.
// ---------------------------------------------------------------------------

function attrOf(el: Element, name: string): string | undefined {
  return el.getAttribute(name) ?? undefined;
}

function parseNumber(raw: string | undefined, fallback: number): number {
  if (raw === undefined || raw.trim() === '') return fallback;
  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

function parseBool(raw: string | undefined, fallback: boolean): boolean {
  const v = raw?.trim().toLowerCase();
  return v === 'true' || v === '1' ? true : v === 'false' || v === '0' ? false : fallback;
}

/** Split a shorthand tuple attribute (`"x y z"`, commas tolerated). */
function tuple(raw: string | undefined): string[] {
  return raw === undefined ? [] : raw.trim().split(/[\s,]+/).filter((t) => t !== '');
}

function vec3(raw: string | undefined, defaults: Readonly<VemlVec3>): VemlVec3 {
  const t = tuple(raw);
  return {
    x: parseNumber(t[0], defaults.x),
    y: parseNumber(t[1], defaults.y),
    z: parseNumber(t[2], defaults.z),
  };
}

function quat(raw: string | undefined): VemlQuaternion {
  const t = tuple(raw);
  return {
    x: parseNumber(t[0], DEFAULT_ROTATION.x),
    y: parseNumber(t[1], DEFAULT_ROTATION.y),
    z: parseNumber(t[2], DEFAULT_ROTATION.z),
    w: parseNumber(t[3], DEFAULT_ROTATION.w),
  };
}

function vec2(raw: string | undefined, defaults: Readonly<VemlVec2>): VemlVec2 {
  const t = tuple(raw);
  return { x: parseNumber(t[0], defaults.x), y: parseNumber(t[1], defaults.y) };
}

// ---------------------------------------------------------------------------
// Warning sink (unknown-entity-type parity, G.2). Attribute/element-level
// warnings are a documented 7.2 refinement.
// ---------------------------------------------------------------------------

class WarningSink {
  readonly warnings: VemlParseWarning[] = [];
  add(kind: VemlParseWarning['kind'], name: string, path: string): void {
    this.warnings.push({ kind, name, path });
  }
}

// ---------------------------------------------------------------------------
// Entity element helpers.
// ---------------------------------------------------------------------------

/** Child elements that are `veml-*` ENTITY elements (structure elements excluded). */
function entityChildren(el: Element): Element[] {
  return Array.from(el.children).filter(
    (c) => c.localName.startsWith(VEML_PREFIX) && !STRUCTURE_LOCALS.has(c.localName),
  );
}

function firstStructure(parent: Element, local: string): Element | undefined {
  for (const c of Array.from(parent.children)) if (c.localName === local) return c;
  return undefined;
}

/** The type's PRIMARY resource wire (first `r`/`rs`/`ar` field) — the `src` target. */
function primaryResourceWire(spec: FieldSpec): string | undefined {
  for (const [, wire, kind] of spec) {
    if (kind === 'r' || kind === 'rs' || kind === 'ar') return wire;
  }
  return undefined;
}

/** Build `base.transform` from the shorthand attributes. */
function parseTransform(el: Element): VemlTransform | undefined {
  const pos = attrOf(el, 'position');
  const rot = attrOf(el, 'rotation');
  const scl = attrOf(el, 'scale');
  const sz = attrOf(el, 'size');
  const ppct = attrOf(el, 'position-percent');
  const spct = attrOf(el, 'size-percent');
  const alignH = attrOf(el, 'align-horizontal');
  const alignV = attrOf(el, 'align-vertical');
  const stretch = attrOf(el, 'stretch-to-parent');

  if (scl !== undefined) {
    return { kind: 'scaletransform', position: vec3(pos, DEFAULT_POSITION), rotation: quat(rot), scale: vec3(scl, DEFAULT_SCALE) };
  }
  if (sz !== undefined) {
    return { kind: 'sizetransform', position: vec3(pos, DEFAULT_POSITION), rotation: quat(rot), size: vec3(sz, DEFAULT_SIZE) };
  }
  if (ppct !== undefined || spct !== undefined || alignH !== undefined || alignV !== undefined || stretch !== undefined) {
    return {
      kind: 'canvastransform',
      positionPercent: vec2(ppct, DEFAULT_POSITION_PERCENT),
      sizePercent: vec2(spct, DEFAULT_SIZE_PERCENT),
      alignHorizontal: alignH as 'center' | 'left' | 'right' | undefined,
      alignVertical: alignV as 'center' | 'top' | 'bottom' | undefined,
      stretchToParent: stretch === undefined ? undefined : parseBool(stretch, false),
    };
  }
  if (pos !== undefined || rot !== undefined) {
    // Position/rotation only → a scaletransform with the default scale (matches
    // the XML shape where an entity with a scaletransform omitting <scale> gets
    // the (1,1,1) default).
    return { kind: 'scaletransform', position: vec3(pos, DEFAULT_POSITION), rotation: quat(rot), scale: vec3(undefined, DEFAULT_SCALE) };
  }
  return undefined; // No transform attrs → absent (XML entity with no <transform>).
}

/** Apply a shared `SUBTYPE_FIELDS` spec, reading each `wire` as an ATTRIBUTE. */
function applyFields(
  el: Element,
  spec: FieldSpec,
  out: Record<string, unknown>,
  worldDocUrl: string,
): void {
  const ref = (raw: string): VemlResourceRef => ({ raw, resolved: resolveWorldUri(raw, worldDocUrl) });
  const srcWire = primaryResourceWire(spec);
  const src = attrOf(el, 'src');
  // `src` fills the primary resource field when that field's own wire is absent.
  const resourceRaw = (wire: string): string | undefined =>
    attrOf(el, wire) ?? (wire === srcWire ? src : undefined);

  for (const [key, wire, kind, dflt] of spec) {
    let value: unknown;
    switch (kind) {
      case 's': value = attrOf(el, wire); break;
      case 'n': { const raw = attrOf(el, wire); const n = raw === undefined ? NaN : Number(raw); value = Number.isFinite(n) ? n : undefined; break; }
      case 'be': value = parseBool(attrOf(el, wire), dflt as boolean); break;
      case 'ne': value = parseNumber(attrOf(el, wire), dflt as number); break;
      case 'r': { const raw = resourceRaw(wire); value = raw ? ref(raw) : undefined; break; }
      case 'rs': { const raw = resourceRaw(wire); value = raw ? tuple(raw).map(ref) : []; break; }
      case 'v3': { const raw = attrOf(el, wire); value = raw !== undefined ? vec3(raw, DEFAULT_POSITION) : undefined; break; }
      case 'q': { const raw = attrOf(el, wire); value = raw !== undefined ? quat(raw) : undefined; break; }
      case 'as': value = attrOf(el, wire); break;
      case 'aD': value = attrOf(el, wire) ?? dflt; break;
      case 'an': { const raw = attrOf(el, wire); value = raw === undefined ? undefined : parseNumber(raw, 0); break; }
      case 'ab': { const raw = attrOf(el, wire); value = raw === undefined ? undefined : parseBool(raw, false); break; }
      case 'ar': { const raw = resourceRaw(wire); value = raw ? ref(raw) : undefined; break; }
      case 'L': value = []; break; // Nested collections deferred to 7.2 (Scope Guard).
    }
    out[key] = value;
  }
}

function parseLink(el: Element, worldDocUrl: string): VemlLink | undefined {
  const href = attrOf(el, 'link') ?? attrOf(el, 'href');
  if (href === undefined) return undefined;
  // A link that does not resolve to http(s) is not a portal.
  const resolvedHref = href ? followableWorldUri(href, worldDocUrl) : '';
  if (resolvedHref === undefined) return undefined;
  return {
    href,
    resolvedHref,
    label: attrOf(el, 'link-label') ?? '',
  };
}

function parseEntity(el: Element, path: string, worldDocUrl: string, sink: WarningSink): VemlEntity {
  // Element localName minus `veml-` IS the xsi:type (mechanical, driftless);
  // a friendly alias resolves to its CANONICAL xsi:type first, so
  // `veml-cube` and `veml-cubemesh` produce the identical `base.type` (G.10).
  const type = resolveAlias(el.localName.slice(VEML_PREFIX.length));
  // Own-property lookup only: a wire-controlled `veml-constructor` /
  // `veml-__proto__` must not reach Object.prototype.
  const spec = Object.prototype.hasOwnProperty.call(SUBTYPE_FIELDS, type)
    ? SUBTYPE_FIELDS[type]
    : undefined;
  if (!spec) sink.add('unknown-entity-type', type || '(missing)', path);

  const base: VemlEntityBase & { known?: false } = {
    type,
    tag: attrOf(el, 'tag'),
    id: attrOf(el, 'id'),
    onLoadEvent: attrOf(el, 'on-load-event'),
    transform: parseTransform(el),
    children: entityChildren(el).map((child, i) =>
      parseEntity(child, `${path} > ${child.localName}[${i}]`, worldDocUrl, sink),
    ),
    synchronizer: attrOf(el, 'synchronizer'),
    placementSockets: [], // The dialect has no placement-socket syntax.
    link: parseLink(el, worldDocUrl),
  };
  if (!spec) {
    base.known = false;
    return base as VemlEntity;
  }
  applyFields(el, spec, base as unknown as Record<string, unknown>, worldDocUrl);
  return base as VemlEntity;
}

// ---------------------------------------------------------------------------
// Structure (background / spawn) + document assembly.
// ---------------------------------------------------------------------------

function kebabToCamel(name: string): string {
  return name.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase());
}

/**
 * `<veml-sky>` → the `lite-procedural-sky` sky map (ergonomics fold 2).
 * Reads the XML parser's exported `SKY_ATTRS` catalog as ATTRIBUTES (identical
 * kebab→camel key + default-typed parse), so a `<veml-sky>` and the XML
 * `<background><lite-procedural-sky>` produce the SAME map (deep-equal, G.11).
 * The VISUAL procedural-sky render is not done here — a `veml-sky` world
 * loads with the neutral clear + neutral IBL fallback.
 */
function parseSky(el: Element): VemlLiteProceduralSky {
  const sky: VemlLiteProceduralSky = {};
  for (const [wire, fallback] of SKY_ATTRS) {
    const raw = el.getAttribute(wire);
    const key = kebabToCamel(wire);
    if (raw === null) {
      if (fallback !== undefined) sky[key] = fallback;
    } else if (typeof fallback === 'boolean') {
      sky[key] = parseBool(raw, fallback);
    } else if (typeof fallback === 'number') {
      sky[key] = parseNumber(raw, fallback);
    } else {
      sky[key] = raw;
    }
  }
  return sky;
}

function parseBackground(worldEl: Element, worldDocUrl: string): VemlBackground | undefined {
  // Precedence mirrors parser.ts parseEnvironment: color > panorama > sky.
  const bg = firstStructure(worldEl, 'veml-background');
  if (bg) {
    const color = attrOf(bg, 'color');
    if (color !== undefined) return { kind: 'color', color };
    const panorama = attrOf(bg, 'panorama');
    if (panorama) return { kind: 'panorama', panorama: { raw: panorama, resolved: resolveWorldUri(panorama, worldDocUrl) } };
  }
  const skyEl = firstStructure(worldEl, 'veml-sky');
  if (skyEl) return { kind: 'lite-procedural-sky', sky: parseSky(skyEl) };
  return undefined;
}

function parseEnvironment(worldEl: Element, worldDocUrl: string, sink: WarningSink): VemlEnvironment {
  const environment: VemlEnvironment = { entities: [] };
  const background = parseBackground(worldEl, worldDocUrl);
  if (background) environment.background = background;

  const spawnEl = firstStructure(worldEl, 'veml-spawn');
  if (spawnEl) {
    environment.spawn = {
      position: vec3(attrOf(spawnEl, 'position'), DEFAULT_POSITION),
      rotation: quat(attrOf(spawnEl, 'rotation')),
    };
  }

  environment.entities = entityChildren(worldEl).map((child, i) =>
    parseEntity(child, `veml-world > ${child.localName}[${i}]`, worldDocUrl, sink),
  );
  return environment;
}

/**
 * The metadata children this dialect carries: the 3.x XML parser's list, by
 * reference, so the two cannot drift. A 4.0 spelling of the one element whose
 * name changed (`synchronization-service`) is accepted as an alias.
 */
export const HTML_METADATA_CHILDREN: readonly string[] = LEGACY_METADATA_CHILDREN;
const METADATA_ALIASES: Record<string, LegacyMetadataChild> = { 'synchronization-service': 'synchronizationservice' };

function metadataChildKind(local: string): LegacyMetadataChild | undefined {
  const name = local.slice(VEML_PREFIX.length);
  if ((LEGACY_METADATA_CHILDREN as readonly string[]).includes(name)) return name as LegacyMetadataChild;
  return Object.prototype.hasOwnProperty.call(METADATA_ALIASES, name) ? METADATA_ALIASES[name] : undefined;
}

type MetadataHandler = (el: Element, metadata: VemlMetadata, worldDocUrl: string) => void;

/** One handler per 3.x metadata child; a child added to the parser's list without one is a type error here. */
const METADATA_HANDLERS: Record<LegacyMetadataChild, MetadataHandler> = {
  title: (el, metadata) => {
    // The root's `title` attribute wins; the child fills in when it is absent.
    if (metadata.title === undefined) {
      const text = (el.textContent ?? '').trim();
      if (text.length > 0) metadata.title = text;
    }
  },
  capability: (el, metadata) => {
    metadata.capabilities.push((el.textContent ?? '').trim());
  },
  script: (el, metadata, worldDocUrl) => {
    // `src` as an attribute (the dialect's way), else the element text (the XML way).
    const raw = attrOf(el, 'src') ?? (el.textContent ?? '').trim();
    if (raw.length === 0) return;
    const script: VemlScriptRef = { raw, resolved: resolveWorldUri(raw, worldDocUrl) };
    const integrity = attrOf(el, 'integrity');
    if (integrity !== undefined) script.integrity = integrity;
    metadata.scripts.push(script);
  },
  inputevent: (el, metadata) => {
    const event: VemlInputEvent = { input: attrOf(el, 'input'), event: attrOf(el, 'event') };
    metadata.inputEvents.push(event);
  },
  controlflags: (el, metadata) => {
    // The XML parser reads each flag as a child element; here each is an attribute.
    const flags: Record<string, string | boolean> = {};
    for (const [key, wire, kind] of CONTROL_FLAG_FIELDS) {
      const raw = attrOf(el, wire);
      if (raw === undefined) continue;
      flags[key] = kind === 'b' ? parseBool(raw, false) : raw;
    }
    metadata.controlFlags = flags as VemlControlFlags;
  },
  synchronizationservice: (el, metadata) => {
    const service: VemlSynchronizationService = {
      type: attrOf(el, 'type'),
      address: attrOf(el, 'address'),
      id: attrOf(el, 'id'),
      session: attrOf(el, 'session'),
    };
    metadata.synchronizationServices.push(service);
  },
};

/**
 * `<veml-metadata>` into the document's metadata, the same shape the XML
 * parsers produce. A child this dialect has no handler for is a named
 * diagnostic (§2's convention): a stated gap, never a silent one.
 */
function parseMetadata(
  worldEl: Element | undefined,
  titleAttr: string | undefined,
  worldDocUrl: string,
  sink: WarningSink,
): VemlMetadata {
  const metadata: VemlMetadata = {
    title: titleAttr,
    capabilities: [],
    scripts: [],
    inputEvents: [],
    synchronizationServices: [],
  };
  const metadataEl = worldEl ? firstStructure(worldEl, 'veml-metadata') : undefined;
  if (!metadataEl) return metadata;
  for (const child of Array.from(metadataEl.children)) {
    if (!child.localName.startsWith(VEML_PREFIX)) continue; // page furniture
    const kind = metadataChildKind(child.localName);
    if (kind === undefined) {
      sink.add('diagnostic', 'veml:3.3:metadata-unsupported', `veml-metadata > ${child.localName}`);
      continue;
    }
    METADATA_HANDLERS[kind](child, metadata, worldDocUrl);
  }
  return metadata;
}

// ---------------------------------------------------------------------------
// Entry point.
// ---------------------------------------------------------------------------

/**
 * Parse a `veml-*` HTML dialect document into the SAME `VemlDocument` the XML
 * parser produces. Never throws — all failure modes land in the report
 * (mirrors parser.ts). A document with no `veml-*` element is "not a world
 * document" (G.1, reuses the `not-veml` report kind).
 */
export function parseVemlHtml(htmlText: string, worldDocUrl: string): VemlParseResult {
  const report: VemlParseReport = { url: worldDocUrl, declaredVersion: null, errors: [], warnings: [] };
  const fail = (kind: 'not-veml' | 'malformed-xml', message: string): VemlParseResult => {
    report.errors.push({ kind, message, url: worldDocUrl });
    return { ok: false, report };
  };

  // Inert one-way parse (THE HARD CONSTRAINT): a fresh HTMLDocument NEVER
  // attached to the live document; no customElements.define anywhere.
  const doc = new DOMParser().parseFromString(htmlText, 'text/html');

  if (!containsVemlElement(doc)) {
    return fail(
      'not-veml',
      `Document at ${worldDocUrl} is an HTML page with no veml-* elements — not a world document.`,
    );
  }

  try {
    const sink = new WarningSink();
    // The HTML dialect declares no XML namespace → 'none' (the current schema,
    // 3.1), which is ALSO the dominant namespace-less XML wire case, so an XML
    // twin and its HTML-dialect twin deep-equal (G.5).
    report.declaredVersion = 'none';

    let title: string | undefined;
    let environment: VemlEnvironment;
    // Prefer a <veml-world> root; else (forward-compat with the inline
    // bootstrap) treat body-level veml-* entity elements as the world.
    let worldEl: Element | undefined;
    const worldList = doc.getElementsByTagName('veml-world');
    if (worldList.length > 0) worldEl = worldList[0];

    // The PRIMARY HTML form: a `veml-world` root
    // carrying `version` is §3.3's mechanical prefixing of the 4.0 vocabulary
    // (the HTML analogue of the §1.4 discriminator — the version-less root is
    // the prototype-era ergonomic dialect below, now the SUGAR tier). Strip
    // the prefix mechanically and hand the subtree to the 4.0 path.
    if (worldEl && attrOf(worldEl, 'version') !== undefined) {
      return parseWorld40Xml(primaryFormToXml(worldEl), worldDocUrl);
    }
    if (worldEl) {
      title = attrOf(worldEl, 'title');
      environment = parseEnvironment(worldEl, worldDocUrl, sink);
    } else {
      const body = doc.body;
      environment = {
        entities: (body ? entityChildren(body) : []).map((child, i) =>
          parseEntity(child, `body > ${child.localName}[${i}]`, worldDocUrl, sink),
        ),
      };
    }

    const document: VemlDocument = {
      declaredVersion: 'none',
      metadata: parseMetadata(worldEl, title, worldDocUrl, sink),
      environment,
    };
    report.warnings.push(...sink.warnings);
    return { ok: true, document, report };
  } catch (err) {
    return fail(
      'malformed-xml',
      `Document at ${worldDocUrl} could not be parsed as an HTML world: ${
        err instanceof Error ? err.message : String(err)
      }`,
    );
  }
}

// ---------------------------------------------------------------------------
// The PRIMARY prefixed form + the sugar expander.
// ---------------------------------------------------------------------------

function escapeXml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/**
 * §3.3's mechanical prefixing, reversed: `veml-world` → `veml`, every other
 * `veml-*` element loses the prefix, attributes and values unchanged. Non-veml
 * elements inside the subtree are page furniture and are ignored (inert
 * one-way parse — the same posture as the ergonomic dialect). Leaf text
 * (e.g. `veml-title`) is preserved.
 */
function primaryFormToXml(el: Element): string {
  const local = el.localName;
  if (!local.startsWith(VEML_PREFIX)) return '';
  const name = local === 'veml-world' ? 'veml' : local.slice(VEML_PREFIX.length);
  const attrs = Array.from(el.attributes)
    .map((a) => ` ${a.name}="${escapeXml(a.value)}"`)
    .join('');
  const children = Array.from(el.children).map(primaryFormToXml).join('');
  if (children.length > 0) return `<${name}${attrs}>${children}</${name}>`;
  const text = (el.textContent ?? '').trim();
  return text.length > 0 ? `<${name}${attrs}>${escapeXml(text)}</${name}>` : `<${name}${attrs}/>`;
}

/** Canonical 3.1-era primitive type → the 4.0 §4.5 shape name. */
const TYPE_TO_SHAPE: Record<string, string> = {
  cubemesh: 'cube',
  spheremesh: 'sphere',
  capsulemesh: 'capsule',
  cylindermesh: 'cylinder',
  planemesh: 'plane',
  torusmesh: 'torus',
  conemesh: 'cone',
  rectangularpyramidmesh: 'rectangular-pyramid',
  tetrahedronmesh: 'tetrahedron',
  prismmesh: 'prism',
  archmesh: 'arch',
};

class SugarExpansionUnsupported extends Error {}

/** An element re-serialized in the PREFIXED form, its name mapped by `rename`; attributes, text and children kept. */
function serializePrefixed(el: Element, rename: (local: string) => string): string {
  const name = rename(el.localName);
  const attrs = Array.from(el.attributes)
    .map((a) => ` ${a.name}="${escapeXml(a.value)}"`)
    .join('');
  const children = Array.from(el.children)
    .filter((c) => c.localName.startsWith(VEML_PREFIX))
    .map((c) => serializePrefixed(c, rename))
    .join('');
  if (children.length > 0) return `<${name}${attrs}>${children}</${name}>`;
  const text = (el.textContent ?? '').trim();
  return text.length > 0 ? `<${name}${attrs}>${escapeXml(text)}</${name}>` : `<${name}${attrs}></${name}>`;
}

/** The 3.x metadata names the 4.0 vocabulary spells differently. */
const METADATA_TO_40: Record<string, string> = { 'veml-synchronizationservice': 'veml-synchronization-service' };
/** 3.x metadata the 4.0 form has no lossless home for: the legacy parser keeps the page. */
const METADATA_NOT_IN_40 = new Set(['veml-inputevent', 'veml-controlflags']);

/** `<veml-metadata>` for the primary form: the title, then every child under its 4.0 name. */
function expandMetadata(world: Element): string {
  const parts: string[] = [];
  const title = attrOf(world, 'title');
  if (title !== undefined) parts.push(`<veml-title>${escapeXml(title)}</veml-title>`);
  const metadataEl = firstStructure(world, 'veml-metadata');
  for (const child of metadataEl ? Array.from(metadataEl.children) : []) {
    if (!child.localName.startsWith(VEML_PREFIX)) continue;
    if (child.localName === 'veml-title' && title !== undefined) continue;
    if (METADATA_NOT_IN_40.has(child.localName)) throw new SugarExpansionUnsupported(child.localName);
    parts.push(
      serializePrefixed(child, (local) =>
        Object.prototype.hasOwnProperty.call(METADATA_TO_40, local) ? METADATA_TO_40[local]! : local,
      ),
    );
  }
  return `<veml-metadata>${parts.join('')}</veml-metadata>`;
}

function vecElement(name: string, raw: string | undefined): string {
  if (raw === undefined) return '';
  const [x = '0', y = '0', z = '0'] = tuple(raw);
  return `<${name} x="${escapeXml(x)}" y="${escapeXml(y)}" z="${escapeXml(z)}"></${name}>`;
}

function quatElement(name: string, raw: string | undefined): string {
  if (raw === undefined) return '';
  const [x = '0', y = '0', z = '0', w = '1'] = tuple(raw);
  return `<${name} x="${escapeXml(x)}" y="${escapeXml(y)}" z="${escapeXml(z)}" w="${escapeXml(w)}"></${name}>`;
}

function expandTransformAttrs(el: Element): string {
  const pos = attrOf(el, 'position');
  const rot = attrOf(el, 'rotation');
  const scl = attrOf(el, 'scale');
  const sz = attrOf(el, 'size');
  if (pos === undefined && rot === undefined && scl === undefined && sz === undefined) return '';
  const inner =
    vecElement('veml-position', pos) +
    quatElement('veml-rotation', rot) +
    (sz !== undefined ? vecElement('veml-size', sz) : vecElement('veml-scale', scl));
  return `<veml-transform>${inner}</veml-transform>`;
}

function expandLinkAttrs(el: Element): string {
  const href = attrOf(el, 'link') ?? attrOf(el, 'href');
  if (href === undefined) return '';
  const label = attrOf(el, 'link-label');
  return `<veml-link href="${escapeXml(href)}"${
    label !== undefined ? ` label="${escapeXml(label)}"` : ''
  }></veml-link>`;
}

function expandEntityEl(el: Element): string {
  const type = resolveAlias(el.localName.slice(VEML_PREFIX.length));
  const tag = attrOf(el, 'tag');
  const id = attrOf(el, 'id');
  const common =
    (tag !== undefined ? ` tag="${escapeXml(tag)}"` : '') +
    (id !== undefined ? ` id="${escapeXml(id)}"` : '');
  const inner =
    expandTransformAttrs(el) + expandLinkAttrs(el) + entityChildren(el).map(expandEntityEl).join('');

  const shape = Object.prototype.hasOwnProperty.call(TYPE_TO_SHAPE, type)
    ? TYPE_TO_SHAPE[type]
    : undefined;
  if (shape !== undefined) {
    const color = attrOf(el, 'color');
    return `<veml-primitive shape="${shape}"${common}${
      color !== undefined ? ` color="${escapeXml(color)}"` : ''
    }>${inner}</veml-primitive>`;
  }
  if (type === 'mesh') {
    const src = attrOf(el, 'src') ?? attrOf(el, 'mesh-resource');
    return `<veml-asset${common}${src !== undefined ? ` src="${escapeXml(src)}"` : ''}>${inner}</veml-asset>`;
  }
  if (type === 'container') {
    return `<veml-container${common}>${inner}</veml-container>`;
  }
  // A 3.1-era surface with no 4.0 vocabulary equivalent (light, audio, text,
  // sky, …): the sugar tier cannot expand it losslessly — the page stays on
  // the legacy dialect parser.
  throw new SugarExpansionUnsupported(el.localName);
}

/**
 * Expand a prototype-era ERGONOMIC dialect page onto the PRIMARY prefixed
 * form (sugar is defined strictly by lossless expansion — never
 * an independent vocabulary). Returns the primary-form page; when the page
 * uses a surface with no 4.0 equivalent (or has no `veml-world`), the
 * original text is returned unchanged and the legacy dialect parser remains
 * its reader.
 */
export function expandSugarToPrimary(htmlText: string): string {
  const doc = new DOMParser().parseFromString(htmlText, 'text/html');
  const world = doc.getElementsByTagName('veml-world')[0];
  if (!world) return htmlText;
  if (attrOf(world, 'version') !== undefined) return htmlText; // already primary

  try {
    const metadata = expandMetadata(world);

    const envParts: string[] = [];
    const spawnEl = firstStructure(world, 'veml-spawn');
    if (spawnEl) {
      envParts.push(
        `<veml-entry-point id="default">${vecElement(
          'veml-position',
          attrOf(spawnEl, 'position'),
        )}${quatElement('veml-rotation', attrOf(spawnEl, 'rotation'))}</veml-entry-point>`,
      );
    }
    const bgEl = firstStructure(world, 'veml-background');
    if (bgEl) {
      const color = attrOf(bgEl, 'color');
      const panorama = attrOf(bgEl, 'panorama');
      if (color !== undefined || panorama !== undefined) {
        envParts.push(
          `<veml-background${color !== undefined ? ` color="${escapeXml(color)}"` : ''}${
            panorama !== undefined ? ` panorama="${escapeXml(panorama)}"` : ''
          }></veml-background>`,
        );
      } else {
        throw new SugarExpansionUnsupported('veml-background (element-content form)');
      }
    }
    if (firstStructure(world, 'veml-sky')) {
      throw new SugarExpansionUnsupported('veml-sky');
    }
    for (const child of entityChildren(world)) envParts.push(expandEntityEl(child));

    return `<!doctype html><html><body><veml-world version="4.0">${metadata}<veml-environment>${envParts.join(
      '',
    )}</veml-environment></veml-world></body></html>`;
  } catch (err) {
    if (err instanceof SugarExpansionUnsupported) return htmlText;
    throw err;
  }
}
